(async () => {
    const base = 'https://junejulyz.github.io/st-regex-manager';
    let v = '';
    try {
        const r = await fetch(base + '/version.txt?t=' + Date.now(), { cache: 'no-store' });
        if (r.ok) v = (await r.text()).trim();
    } catch (e) { console.warn('[RegexManager] 版本检测失败，将强制拉取最新：', e); }
    await import(base + '/regex-manager.js?v=' + (v || Date.now()));
})();
